import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { loadMultiFunctionInfo } from '../../serverless/config.js';
import { TEST_CONFIG_V202603 as TEST_CONFIG, TEST_CONFIG_V20251, } from './fixtures/constants.js';
describe('loadMultiFunctionInfo (v2026.03)', () => {
    it('loads app functions from pre-resolved IR data', () => {
        const result = loadMultiFunctionInfo(TEST_CONFIG);
        expect(result.appFunctions).toHaveProperty('returns-text');
        expect(result.appFunctions['returns-text'].file).toEqual(expect.stringContaining('func-returns-text.cjs'));
        expect(path.isAbsolute(result.appFunctions['returns-text'].file)).toBe(true);
        expect(result.appFunctions['returns-text'].secrets).toEqual([]);
        expect(Object.keys(result.appFunctions).length).toBeGreaterThan(0);
    });
    it('includes secret keys from IR data', () => {
        const result = loadMultiFunctionInfo(TEST_CONFIG);
        expect(result.appFunctions).toHaveProperty('uses-secret');
        expect(result.appFunctions['uses-secret'].secrets).toEqual(['PHRASE']);
    });
    it('throws when no appFunctions are provided', () => {
        const configWithoutFunctions = {
            ...TEST_CONFIG,
            appFunctions: undefined,
        };
        expect(() => loadMultiFunctionInfo(configWithoutFunctions)).toThrow('No app function data provided');
    });
    it('throws when appFunctions is empty', () => {
        const configWithEmptyFunctions = {
            ...TEST_CONFIG,
            appFunctions: {},
        };
        expect(() => loadMultiFunctionInfo(configWithEmptyFunctions)).toThrow('No app function data provided');
    });
    it('returns srcDir derived from the first resolved path', () => {
        const result = loadMultiFunctionInfo(TEST_CONFIG);
        expect(result.srcDir).toEqual(expect.stringContaining(path.join('unified', 'functions')));
    });
});
describe('loadMultiFunctionInfo (v2025.1)', () => {
    it('loads app functions from serverless.json', () => {
        const result = loadMultiFunctionInfo(TEST_CONFIG_V20251);
        expect(Object.keys(result.appFunctions).length).toBeGreaterThan(0);
    });
});
